    /// <summary>Converts a raw video buffer into the specified output caps.</summary>
    /// <remarks>
    /// <para>The output caps can be any raw video formats or any image formats (jpeg, png, ...).</para>
    /// <para>The width, height and pixel-aspect-ratio can also be specified in the output caps.</para>
    /// </remarks>
    /// <param name="sample">The <c>sample</c> argument.</param>
    /// <param name="toCaps">The <c>toCaps</c> argument.</param>
    /// <param name="timeout">The <c>timeout</c> argument.</param>
    /// <returns>
    /// The converted #GstSample, or %NULL if an error happened (in which case @err
    /// will point to the #GError).
    /// </returns>
    /// <exception cref="Gst.GLib.GException">The native call failed.</exception>
    public static Gst.Sample? VideoConvertSample(Gst.Sample sample, Gst.Caps toCaps, Gst.ClockTime timeout)
    {
        ArgumentNullException.ThrowIfNull(sample);
        ArgumentNullException.ThrowIfNull(toCaps);
        nint errorNative = 0;
        nint nativeResult = GstVideoConvertSample(sample.Handle, toCaps.Handle, timeout.Nanoseconds, &errorNative);
        System.GC.KeepAlive(sample);
        System.GC.KeepAlive(toCaps);
        if (errorNative != 0 && nativeResult != 0)
        {
            // The call failed and transferred a value all the same. The throw
            // below puts it out of reach, so it is released rather than leaked.
            Gst.Sample.FromNative(nativeResult, Gst.Interop.Transfer.Full)?.Dispose();
        }
        Gst.GLib.GException.ThrowIfSet(ref errorNative);
        return Gst.Sample.FromNative(nativeResult, Gst.Interop.Transfer.Full);
    }

